document.querySelectorAll('[data-page]').forEach(b=>b.addEventListener('click',async()=>{document.querySelectorAll('.research-page').forEach(s=>s.hidden=s.id!==b.dataset.page);document.querySelectorAll('[data-page]').forEach(a=>{a.classList.toggle('active',a===b);a.setAttribute('aria-pressed',String(a===b))});try{if(b.dataset.page==='trajectories')await loadTrajectories();if(b.dataset.page==='simulation')await simulate()}catch(e){$('message').textContent=e.message}}));
