function importance(){const task=$('importance-task').value,rr=report.permutation_groups[task],max=Math.max(...rr.map(r=>Math.abs(r.mean_loss_increase)),.001);$('importance').innerHTML=rr.map(r=>`<div class="bar-row"><span>${groups[r.group]||esc(r.group)}</span><div class="bar-track"><div class="bar-fill" style="width:${100*Math.max(0,r.mean_loss_increase)/max}%"></div></div><span>${fmt(r.mean_loss_increase,4)}</span></div>`).join('')}
